def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Base update magnitudes: donate gets a small positive, defect gets a larger negative
    if observation["action"] == "donate":
        delta = 0.2
    else:
        delta = -0.3

    # Modulate updates based on own experience: if we've been exploited, penalize defectors more
    if my_history:
        # Count how often we donated and partner didn't
        exploited = sum(1 for entry in my_history if entry["action"] and not entry["partner_action"])
        total = len(my_history)
        exploit_rate = exploited / total if total > 0 else 0
        # If we've been exploited often, increase the penalty for defection
        if not observation["action"] == "donate":
            delta -= 0.1 * min(exploit_rate, 0.5)  # extra penalty up to 0.05
        else:
            delta += 0.05 * (1 - exploit_rate)  # small bonus for donating in good environment

    # Stabilize updates in later rounds
    if round_num > 50:
        delta *= 0.5

    new_reputation = current_reputation + delta
    return max(-1.0, min(1.0, new_reputation))


def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Compute own donation rate from history
    if my_history:
        own_donations = sum(1 for entry in my_history if entry["action"])
        own_rate = own_donations / len(my_history)
    else:
        own_rate = 0.5  # neutral default

    # Base threshold: slightly positive, but adjusted by own cooperation level
    base_threshold = 0.3 + 0.3 * (1 - own_rate)  # more cooperative -> lower threshold

    # In later rounds, become more trusting
    if round_num > 30:
        base_threshold -= 0.1

    # If our last partner defected, be slightly more cautious
    if my_history and len(my_history) >= 2:
        if not my_history[-1]["partner_action"]:
            base_threshold += 0.1

    # Clamp threshold to reasonable range
    threshold = max(0.0, min(0.8, base_threshold))
    return recipient_reputation > threshold
